import pdfplumber
import pandas as pd
import json

def get_pdf_data(path):
    data = {}
    headers = None
    numeric_fields = ['Salary', 'Years', 'Score']

    with pdfplumber.open(path) as pdf:
        for page in pdf.pages:
            tables = page.extract_tables()
            for table in tables:
                if not table:
                    continue

                # Assume first row of first table is header
                if headers is None:
                    headers = table[0]
                    rows = table[1:]
                else:
                    # If headers repeat in subsequent tables, skip them
                    if table[0] == headers:
                        rows = table[1:]
                    else:
                        rows = table

                for row in rows:
                    # Create a dictionary for the row
                    record = dict(zip(headers, row))

                    # Clean and convert types
                    for key, value in record.items():
                        if value is None:
                            record[key] = ""
                            continue

                        if key in numeric_fields:
                            try:
                                # Remove common currency/formatting symbols if present
                                clean_val = str(value).replace(',', '').replace('$', '').replace(' ', '')
                                if '.' in clean_val:
                                    record[key] = float(clean_val)
                                else:
                                    record[key] = int(clean_val)
                            except ValueError:
                                # Keep as string if conversion fails, though it shouldn't for valid data
                                record[key] = value

                    # ID is the key
                    if 'ID' in record and record['ID']:
                        data[record['ID']] = record

    return data

def get_excel_data(path):
    df = pd.read_excel(path)
    # Replace NaN with None or empty string to match PDF extraction behavior if needed
    # But usually better to keep as is and handle during comparison.
    # Converting to dict records
    records = df.to_dict('records')
    data = {}
    for record in records:
        # Normalize types for JSON serialization (numpy types to python types)
        for key, value in record.items():
            if pd.isna(value):
                record[key] = "" # Treat NaN as empty string
            elif isinstance(value, (int, float)):
                 record[key] = value
            else:
                 record[key] = str(value)

        if 'ID' in record:
            data[record['ID']] = record
    return data

def compare_data(old_data, new_data):
    deleted = []
    modified = []

    # Check for deleted
    for emp_id in old_data:
        if emp_id not in new_data:
            deleted.append(emp_id)
        else:
            # Check for modifications
            old_record = old_data[emp_id]
            new_record = new_data[emp_id]

            # Fields to compare (all keys in old_record except ID)
            for key in old_record:
                if key == 'ID':
                    continue

                old_val = old_record.get(key)
                new_val = new_record.get(key)

                # Type normalization for comparison
                # Excel might give 55000 (int), PDF might give 55000 (int) or 55000.0 (float)
                # Let's try to align them.

                # If both are numbers, compare with tolerance? No, strict equality usually for currency/IDs.
                # But float/int mismatch can happen.

                # Simple equality check first
                if old_val != new_val:
                    # Double check for numeric mismatch (5000 vs 5000.0)
                    is_numeric_mismatch = False
                    if isinstance(old_val, (int, float)) and isinstance(new_val, (int, float)):
                        if old_val == new_val: # This handles 5 == 5.0
                            is_numeric_mismatch = True

                    if not is_numeric_mismatch:
                        modified.append({
                            "id": emp_id,
                            "field": key,
                            "old_value": old_val,
                            "new_value": new_val
                        })

    return deleted, modified

def main():
    pdf_path = "/root/employees_backup.pdf"
    xlsx_path = "/root/employees_current.xlsx"
    output_path = "/root/diff_report.json"

    print("Reading PDF...")
    old_data = get_pdf_data(pdf_path)
    print(f"Loaded {len(old_data)} records from PDF.")

    print("Reading Excel...")
    new_data = get_excel_data(xlsx_path)
    print(f"Loaded {len(new_data)} records from Excel.")

    print("Comparing...")
    deleted, modified = compare_data(old_data, new_data)

    # Sort results
    deleted.sort()
    modified.sort(key=lambda x: x['id'])

    report = {
        "deleted_employees": deleted,
        "modified_employees": modified
    }

    with open(output_path, 'w') as f:
        json.dump(report, f, indent=2)

    print(f"Report written to {output_path}")
    print(json.dumps(report, indent=2))

if __name__ == "__main__":
    main()

